import React, { useState } from 'react';
import { IterationData } from '../../types';

interface IterationTableProps {
    history: IterationData[];
    solution: number[];
}

export const IterationTable: React.FC<IterationTableProps> = ({ history, solution }) => {
    const [showAll, setShowAll] = useState<boolean>(false);

    const displayedHistory = showAll ? history : history.slice(-10);
    const hasMore = history.length > 10;


    const formatValue = (value: number): string => {
        if (value === 0) return "0";

        return value.toLocaleString('ru-RU', {
            minimumFractionDigits: 0,
            maximumFractionDigits: 10,
            useGrouping: false
        }).replace(',', '.');
    };

    const formatError = (value: number): string => {
        if (value === 0) return "0";
        return value.toFixed(12).replace(/\.?0+$/, '');
    };

    return (
        <div className="space-y-3">
            <div className="overflow-x-auto rounded-lg border">
                <table className="min-w-full divide-y divide-gray-200">
                    <thead className="bg-gray-100">
                    <tr>
                        <th className="px-4 py-3 text-left text-xs font-medium text-gray-600 uppercase tracking-wider">
                            №
                        </th>
                        {solution.map((_, i) => (
                            <th key={i} className="px-4 py-3 text-left text-xs font-medium text-gray-600 uppercase tracking-wider">
                                x<sub>{i + 1}</sub>
                            </th>
                        ))}
                        <th className="px-4 py-3 text-left text-xs font-medium text-gray-600 uppercase tracking-wider">
                            max |Δ|
                        </th>
                    </tr>
                    </thead>
                    <tbody className="bg-white divide-y divide-gray-200">
                    {displayedHistory.map((iter, idx) => (
                        <tr
                            key={iter.iteration}
                            className={`hover:bg-gray-50 transition-colors ${
                                idx === displayedHistory.length - 1 ? 'bg-green-50' : ''
                            }`}
                        >
                            <td className="px-4 py-2 whitespace-nowrap text-sm font-medium text-gray-900">
                                {iter.iteration}
                            </td>
                            {iter.x.map((val, i) => (
                                <td key={i} className="px-4 py-2 whitespace-nowrap text-sm font-mono text-gray-600">
                                    {formatValue(val)}
                                </td>
                            ))}
                            <td className="px-4 py-2 whitespace-nowrap text-sm font-mono text-red-600 font-medium">
                                {formatError(iter.maxError)}
                            </td>
                        </tr>
                    ))}
                    </tbody>
                </table>
            </div>

            {hasMore && (
                <button
                    onClick={() => setShowAll(!showAll)}
                    className="text-sm text-blue-600 hover:text-blue-800"
                >
                    {showAll ? 'Показать последние 10 итераций' : `Показать все ${history.length} итераций`}
                </button>
            )}

            <p className="text-xs text-gray-500">
                * Выделена последняя итерация
            </p>
        </div>
    );
};
